package com.primehr.security;
import com.primehr.integration.administrative.*;import org.junit.jupiter.api.Test;import org.springframework.security.access.AccessDeniedException;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class LdEvaluationPermissionGuardTest {@Test void actionsAndFeedScopeFailClosed(){AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);LdEvaluationPermissionGuard guard=new LdEvaluationPermissionGuard(client);when(client.resolve(LdEvaluationPermissionGuard.EVALUATION,"token")).thenReturn(permission(true,true,true,true,true,PermissionDataScope.OWN_RECORDS));when(client.resolve(LdEvaluationPermissionGuard.COMPLETION_FEED,"token")).thenReturn(permission(true,false,false,false,false,PermissionDataScope.ASSIGNED_RECORDS));assertThat(guard.require(LdEvaluationPermissionGuard.EVALUATION,PrimeHrAction.SUBMIT,"token")).isEqualTo(PermissionDataScope.OWN_RECORDS);assertThatThrownBy(()->guard.require(LdEvaluationPermissionGuard.COMPLETION_FEED,PrimeHrAction.ACCESS,"token")).isInstanceOf(AccessDeniedException.class);}private EffectiveFeaturePermission permission(boolean access,boolean add,boolean edit,boolean submit,boolean approve,PermissionDataScope scope){return new EffectiveFeaturePermission("feature",false,access,add,edit,false,false,submit,approve,false,false,false,scope);}}
